CREATE TABLE IF NOT EXISTS "Accounts"("Id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"Name" TEXT NOT NULL,"UserId" TEXT NOT NULL,"IsActive" BOOLEAN NOT NULL,"CreatedAt" TIMESTAMP NOT NULL DEFAULT (now() AT TIME ZONE 'utc'),"UpdatedAt" TIMESTAMP NULL,CONSTRAINT FK_Accounts_AspNetUsers_UserId FOREIGN KEY ("UserId") REFERENCES "AspNetUsers"("Id") ON DELETE RESTRICT);